'use strict';

// MODULES //

var logGradient = require( '@stdlib/ml/base/loss/float64/log-gradient' );
var huberGradient = require( '@stdlib/ml/base/loss/float64/huber-gradient' );
var hingeGradient = require( '@stdlib/ml/base/loss/float64/hinge-gradient' );
var squaredHingeGradient = require( '@stdlib/ml/base/loss/float64/squared-hinge-gradient' );
var squaredErrorGradient = require( '@stdlib/ml/base/loss/float64/squared-error-gradient' );
var modifiedHuberGradient = require( '@stdlib/ml/base/loss/float64/modified-huber-gradient' );
var epsilonInsensitiveGradient = require( '@stdlib/ml/base/loss/float64/epsilon-insensitive-gradient' );
var squaredEpsilonInsensitiveGradient = require( '@stdlib/ml/base/loss/float64/squared-epsilon-insensitive-gradient' );


// VARIABLES //

/**
* Loss function gradients, indexed by loss function enumeration constant.
*
* @private
* @name LOSS_FUNCTIONS
* @constant
* @type {Array}
*
* @example
* var f = LOSS_FUNCTIONS[ 1 ];
* // returns <Function>
*/
var LOSS_FUNCTIONS = [
	epsilonInsensitive,        // 0: epsilon-insensitive
	hinge,                     // 1: hinge
	huber,                     // 2: huber
	log,                       // 3: log
	modifiedHuber,             // 4: modified-huber
	perceptron,                // 5: perceptron
	squaredEpsilonInsensitive, // 6: squared-epsilon-insensitive
	squaredError,              // 7: squared-error
	squaredHinge               // 8: squared-hinge
];


// FUNCTIONS //

/**
* Computes the gradient of the hinge loss.
*
* Note:
*
* -   Here `params` => `[ ]` (empty)
*
* @private
* @param {number} y - target value
* @param {number} p - predicted value
* @param {Float64Array} params - strided array containing loss function specific parameters.
* @returns {number} loss gradient
*/
function hinge( y, p, params ) { // eslint-disable-line no-unused-vars
	return hingeGradient( 1.0, 1.0, y, p );
}

/**
* Computes the gradient of the perceptron loss.
*
* Note:
*
* -   Here `params` => `[ ]` (empty)
*
* @private
* @param {number} y - target value
* @param {number} p - predicted value
* @param {Float64Array} params - strided array containing loss function specific parameters.
* @returns {number} loss gradient
*/
function perceptron( y, p, params ) { // eslint-disable-line no-unused-vars
	return hingeGradient( 1.0, 0.0, y, p );
}

/**
* Computes the gradient of the log loss.
*
* Note:
*
* -   Here `params` => `[ ]` (empty)
*
* @private
* @param {number} y - target value
* @param {number} p - predicted value
* @param {Float64Array} params - strided array containing loss function specific parameters.
* @returns {number} loss gradient
*/
function log( y, p, params ) { // eslint-disable-line no-unused-vars
	return logGradient( 1.0, y, p );
}

/**
* Computes the gradient of the squared hinge loss.
*
* Note:
*
* -   Here `params` => `[ ]` (empty)
*
* @private
* @param {number} y - target value
* @param {number} p - predicted value
* @param {Float64Array} params - strided array containing loss function specific parameters.
* @returns {number} loss gradient
*/
function squaredHinge( y, p, params ) { // eslint-disable-line no-unused-vars
	return squaredHingeGradient( 1.0, y, p );
}

/**
* Computes the gradient of the modified Huber loss.
*
* Note:
*
* -   Here `params` => `[ ]` (empty)
*
* @private
* @param {number} y - target value
* @param {number} p - predicted value
* @param {Float64Array} params - strided array containing loss function specific parameters.
* @returns {number} loss gradient
*/
function modifiedHuber( y, p, params ) { // eslint-disable-line no-unused-vars
	return modifiedHuberGradient( 1.0, y, p );
}

/**
* Computes the gradient of the squared error loss.
*
* Note:
*
* -   Here `params` => `[ ]` (empty)
*
* @private
* @param {number} y - target value
* @param {number} p - predicted value
* @param {Float64Array} params - strided array containing loss function specific parameters.
* @returns {number} loss gradient
*/
function squaredError( y, p, params ) { // eslint-disable-line no-unused-vars
	return squaredErrorGradient( 1.0, y, p );
}

/**
* Computes the gradient of the Huber loss.
*
* Note:
*
* -   Here `params` => `[ ]` (empty)
*
* @private
* @param {number} y - target value
* @param {number} p - predicted value
* @param {Float64Array} params - strided array containing loss function specific parameters.
* @returns {number} loss gradient
*/
function huber( y, p, params ) { // eslint-disable-line no-unused-vars
	return huberGradient( 1.0, y, p );
}

/**
* Computes the gradient of the epsilon-insensitive loss.
*
* Note:
*
* -   Here `params` => `[ epsilon ]`
*
* @private
* @param {number} y - target value
* @param {number} p - predicted value
* @param {Float64Array} params - strided array containing loss function specific parameters.
* @returns {number} loss gradient
*/
function epsilonInsensitive( y, p, params ) {
	return epsilonInsensitiveGradient( 1.0, params[ 0 ], y, p );
}

/**
* Computes the gradient of the squared epsilon-insensitive loss.
*
* Note:
*
* -   Here `params` => `[ epsilon ]`
*
* @private
* @param {number} y - target value
* @param {number} p - predicted value
* @param {Float64Array} params - strided array containing loss function specific parameters.
* @returns {number} loss gradient
*/
function squaredEpsilonInsensitive( y, p, params ) {
	return squaredEpsilonInsensitiveGradient( 1.0, params[ 0 ], y, p );
}


// EXPORTS //

module.exports = LOSS_FUNCTIONS;
